const { chromium } = require('playwright');

const css = `*{box-sizing:border-box} body{margin:0;font:16px sans-serif}
  .c{display:flex;width:400px;height:120px} .i{width:60px}`;

(async () => {
  const nav = await chromium.launch({ args: ['--no-sandbox'] });
  const pag = await nav.newPage({ viewport: { width: 800, height: 600 } });
  // Devuelve una columna de las cajas de los hijos (x, y, w o h), redondeada a 2 decimales
  const medir = async (estilo, hijos, campo) => {
    await pag.setContent(`<!doctype html><style>${css}</style><div class="c" style="${estilo}">${hijos}</div>`);
    return pag.$$eval('.c > *', (es, campo) => es.map(e => {
      const r = e.getBoundingClientRect();
      return Math.round({ x: r.x, y: r.y, w: r.width, h: r.height }[campo] * 100) / 100;
    }).join(', '), campo);
  };
  const tres = '<div class="i" style="height:40px"></div>'.repeat(3);
  console.log('--- eje principal (fila): posición x de tres cajas de 60 en 400');
  for (const j of ['flex-start', 'center', 'flex-end', 'space-between', 'space-around', 'space-evenly'])
    console.log(j.padEnd(14), 'x =', await medir(`justify-content:${j}`, tres, 'x'));
  const mix = '<div class="i" style="height:30px"></div><div class="i" style="height:60px"></div><div class="i">Ab</div>';
  console.log('--- eje transversal: alto 30, alto 60 y una sin alto (con el texto «Ab»), en un contenedor de 120');
  for (const a of ['stretch', 'flex-start', 'center', 'flex-end'])
    console.log(a.padEnd(14), 'y =', (await medir(`align-items:${a}`, mix, 'y')).padEnd(14), 'alto =', await medir(`align-items:${a}`, mix, 'h'));
  console.log('--- centrar y empujar');
  console.log('centrar una caja de 60x40  x, y =', await medir('justify-content:center;align-items:center', '<div class="i" style="height:40px"></div>', 'x'), '/', await medir('justify-content:center;align-items:center', '<div class="i" style="height:40px"></div>', 'y'));
  console.log('margin-left:auto al último x =', await medir('', '<div class="i"></div><div class="i"></div><div class="i" style="margin-left:auto"></div>', 'x'));
  console.log('columna, justify center    y =', await medir('flex-direction:column;justify-content:center', '<div class="i" style="height:20px"></div><div class="i" style="height:20px"></div>', 'y'));
  console.log('align-content sin wrap     y =', await medir('align-content:center;align-items:flex-start', '<div class="i" style="height:40px"></div>', 'y'), '| con wrap y =', await medir('flex-wrap:wrap;align-content:center;align-items:flex-start', '<div class="i" style="height:40px"></div>', 'y'));
  console.log('columna con alto automático, alto del contenedor =', await pag.evaluate(() => {
    document.body.innerHTML = '<div class="c" style="height:auto;flex-direction:column;justify-content:center"><div class="i" style="height:20px"></div></div>';
    return document.querySelector('.c').getBoundingClientRect().height;
  }));
  console.log('gap: 20px entre tres cajas de 60  x =', await medir('gap:20px', tres, 'x'));
  await nav.close();
})();

const { chromium } = require('playwright');

const css = `*{box-sizing:border-box} body{margin:0;font:16px sans-serif}
  .c{display:flex;height:60px} .i{background:#9cf}`;

(async () => {
  const nav = await chromium.launch({ args: ['--no-sandbox'] });
  const pag = await nav.newPage({ viewport: { width: 800, height: 600 } });
  // hijos: lista de [estilo, texto]; devuelve los anchos (o las posiciones x,y) de cada hijo
  const medir = async (ancho, extra, hijos, que = 'w') => {
    await pag.setContent(`<!doctype html><style>${css}</style><div class="c" style="width:${ancho}px;${extra}">${hijos.map(([e, t]) => `<div class="i" style="${e}">${t || ''}</div>`).join('')}</div>`);
    return pag.$$eval('.c > *', (es, que) => es.map(e => {
      const r = e.getBoundingClientRect(), f = n => Math.round(n * 100) / 100;
      return que === 'w' ? f(r.width) : `(${f(r.x)}, ${f(r.y)})`;
    }).join(que === 'w' ? ', ' : ' '), que);
  };
  const b = (flex, extra = '') => [`flex:${flex};${extra}`];
  console.log('--- crecer: contenedor de 600, tres cajas de base 100');
  console.log('grow 1, 2, 0       anchos =', await medir(600, '', [b('1 0 100px'), b('2 0 100px'), b('0 0 100px')]));
  console.log('grow 1 y 3 (150)   anchos =', await medir(600, '', [b('1 0 150px'), b('3 0 150px')]));
  console.log('--- encoger (con min-width:0 para que nada frene el encogimiento)');
  console.log('en 400: 200, 200, 200  anchos =', await medir(400, '', [b('0 1 200px', 'min-width:0'), b('0 1 200px', 'min-width:0'), b('0 1 200px', 'min-width:0')]));
  console.log('en 400: 300, 200, 100  anchos =', await medir(400, '', [b('0 1 300px', 'min-width:0'), b('0 1 200px', 'min-width:0'), b('0 1 100px', 'min-width:0')]));
  console.log('en 400: 300 fijo y 200 anchos =', await medir(400, '', [b('0 0 300px'), b('0 1 200px', 'min-width:0')]));
  console.log('width:100 con basis:200 ancho =', await medir(400, '', [['width:100px;flex-basis:200px;flex-shrink:0']]));
  console.log('en 240: 200 y 100      anchos =', await medir(240, '', [b('0 1 200px', 'min-width:0'), b('0 1 100px', 'min-width:0')]));
  console.log('barra lateral      anchos =', await medir(800, '', [b('0 0 240px'), b('1')]));
  console.log('--- flex: 1 contra flex: auto (contenedor de 500, textos de distinto largo)');
  const t = ['Pedido', 'Pedido en preparación, listo para despachar', 'OK'];
  for (const f of ['1', 'auto'])
    console.log(('flex: ' + f).padEnd(18), 'anchos =', await medir(500, '', t.map(x => [`flex:${f}`, x])));
  console.log('--- el mínimo automático: una palabra larguísima en una caja con flex: 1 (contenedor de 400)');
  const larga = 'ABCDEFGHIJKLMNOPQRSTUVWXYZABCDEFGHIJKLMNOPQRSTUVWXYZ';
  console.log('min-width:auto     anchos =', await medir(400, '', [['flex:1', larga], ['flex:1', 'Otro']]));
  console.log('min-width:0        anchos =', await medir(400, '', [['flex:1;min-width:0;overflow-wrap:anywhere', larga], ['flex:1', 'Otro']]));
  console.log('--- gap y wrap: cinco cajas de 150 en un contenedor de 500 con gap de 10');
  const cinco = Array(5).fill(['width:150px;height:40px']);
  const cr = Array(5).fill(['width:150px;height:40px;flex-grow:1']);
  console.log('wrap               (x, y) =', await medir(500, 'height:auto;flex-wrap:wrap;gap:10px', cinco, 'xy'));
  console.log('wrap + flex-grow:1 anchos =', await medir(500, 'height:auto;flex-wrap:wrap;gap:10px', cr));
  console.log('sin wrap           anchos =', await medir(500, 'height:auto;gap:10px', cinco));
  await nav.close();
})();

/* Barra de navegación: logo y enlaces a la izquierda, usuario a la derecha */
.barra {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 16px;
}
.barra .usuario { margin-left: auto; }

/* Tarjetas que pasan a la línea siguiente */
.tarjetas {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.tarjetas > .tarjeta { flex: 0 0 150px; }

/* Barra lateral fija y contenido flexible */
.pagina { display: flex; }
.pagina > .lateral { flex: 0 0 240px; }
.pagina > .contenido { flex: 1; min-width: 0; }
